//		Exec(ctx)
func (_c *ReportSnapshotCreateBulk) OnConflictColumns(columns ...string) *ReportSnapshotUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &ReportSnapshotUpsertBulk{
		create: _c,
	}
}

// ReportSnapshotUpsertBulk is the builder for "upsert"-ing
// a bulk of ReportSnapshot nodes.
type ReportSnapshotUpsertBulk struct {
	create *ReportSnapshotCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.ReportSnapshot.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(reportsnapshot.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *ReportSnapshotUpsertBulk) UpdateNewValues() *ReportSnapshotUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(reportsnapshot.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(reportsnapshot.FieldCreatedAt)
			}
			if _, exists := b.mutation.TenantID(); exists {
				s.SetIgnore(reportsnapshot.FieldTenantID)
			}
			if _, exists := b.mutation.RecordID(); exists {
				s.SetIgnore(reportsnapshot.FieldRecordID)
			}
			if _, exists := b.mutation.UserID(); exists {
				s.SetIgnore(reportsnapshot.FieldUserID)
			}
		}
	}))
	return u
}

// Ignore sets each column to itself in case of conflict.
// Using this option is equivalent to using:
//
//	client.ReportSnapshot.Create().
//		OnConflict(sql.ResolveWithIgnore()).
//		Exec(ctx)
func (u *ReportSnapshotUpsertBulk) Ignore() *ReportSnapshotUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithIgnore())
	return u
}

// DoNothing configures the conflict_action to `DO NOTHING`.
// Supported only by SQLite and PostgreSQL.
func (u *ReportSnapshotUpsertBulk) DoNothing() *ReportSnapshotUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.DoNothing())
	return u
}

// Update allows overriding fields `UPDATE` values. See the ReportSnapshotCreateBulk.OnConflict
// documentation for more info.
func (u *ReportSnapshotUpsertBulk) Update(set func(*ReportSnapshotUpsert)) *ReportSnapshotUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&ReportSnapshotUpsert{UpdateSet: update})
	}))
	return u
}

